use std::io::Read;
fn main(){let mut input=String::new();std::io::stdin().read_to_string(&mut input).unwrap();let recipes:serde_json::Value=serde_json::from_str(&input).unwrap();let rows=recipes.as_array().unwrap().iter().map(|r|{let page=[r["page"][0].as_f64().unwrap(),r["page"][1].as_f64().unwrap()];let phase=[r["phase"][0].as_f64().unwrap(),r["phase"][1].as_f64().unwrap()];match ingetrazo_gui::composer_border::source_paper_spans(page,r["margin"].as_f64().unwrap(),r["density"].as_f64().unwrap(),phase){Ok(layers)=>serde_json::json!({"name":r["name"],"layers":layers.into_iter().map(|(s,c)|serde_json::json!({"premul":c.qt_premultiplied8().unwrap().map(|v|(v*255.).round()as u8),"spans":s.into_iter().map(|v|[v.x,v.y,v.len as i32,v.coverage as i32]).collect::<Vec<_>>()})).collect::<Vec<_>>()}),Err(e)=>serde_json::json!({"name":r["name"],"error":e})}}).collect::<Vec<_>>();println!("{}",serde_json::to_string(&rows).unwrap());}
